From 18a1f62bc14afded0af9949681d9adf3ae18f812 Mon Sep 17 00:00:00 2001
From: =?UTF-8?q?Niccol=C3=B2=20Venerandi?= <niccolo@venerandi.com>
Date: Sat, 21 Nov 2026 02:56:01 +0100
Subject: [PATCH] applets/lock_logout: react to the widget's keyboard shortcut

The widget had no handler for its activation, so the shortcut set in its
settings did nothing. It now runs the action when only one button is shown,
and otherwise gives keyboard focus to the first button so it can be picked.

BUG: 500462
---
 applets/lock_logout/main.qml | 21 ++++++++++++++++++++-
 1 file changed, 20 insertions(+), 1 deletion(-)

diff --git a/applets/lock_logout/main.qml b/applets/lock_logout/main.qml
index d89b3a0b43..1b56bd1016 100644
--- a/applets/lock_logout/main.qml
+++ b/applets/lock_logout/main.qml
@@ -21,6 +21,8 @@ PlasmoidItem {
     property bool initialized: false

     preferredRepresentation: fullRepresentation
+
+    Plasmoid.onActivated: (fullRepresentationItem as Flow)?.activate()
     fullRepresentation: Flow {
         id: lockout

@@ -170,7 +172,7 @@ PlasmoidItem {
                     anchors.centerIn: parent
                     source: iconDelegate.model.icon
                     scale: tapHandler.pressed ? 0.9 : 1
-                    active: iconDelegate.containsMouse
+                    active: iconDelegate.containsMouse || iconDelegate.activeFocus
                 }
             }
         }
@@ -178,5 +180,22 @@ PlasmoidItem {
         function performOperation(operation) {
             session[operation]()
         }
+
+        function activate() {
+            const visibleItems = [];
+            for (let i = 0; i < items.count; ++i) {
+                if (items.itemAt(i).visible) {
+                    visibleItems.push(items.itemAt(i));
+                }
+            }
+            if (visibleItems.length === 1) {
+                performOperation(visibleItems[0].operation);
+            } else if (visibleItems.length > 1) {
+                if (Window.window && (Window.window.flags & Qt.WindowDoesNotAcceptFocus)) {
+                    Plasmoid.containment.status = PlasmaCore.Types.AcceptingInputStatus;
+                }
+                visibleItems[0].forceActiveFocus(Qt.ShortcutFocusReason);
+            }
+        }
     }
 }
